"use server";

import { revalidatePath } from "next/cache";

export async function toggleNotificationPreference(formData: FormData) {
  const userId = formData.get("userId") as string;
  const currentValue = formData.get("enabled") === "true";

  await savePreference(userId, !currentValue);

  revalidatePath("/");
}

async function savePreference(userId: string, enabled: boolean) {
  return { userId, enabled };
}

