import { toggleNotificationPreference } from "./actions";

async function getPreference(userId: string) {
  return { enabled: false };
}

export default async function Home() {
  const userId = "user_1";
  const { enabled } = await getPreference(userId);

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <input type="hidden" name="userId" value={userId} />
        <input type="hidden" name="enabled" value={String(enabled)} />
        <label>
          <input type="checkbox" defaultChecked={enabled} />
          Enable notifications
        </label>
        <button type="submit">
          {enabled ? "Turn off" : "Turn on"}
        </button>
      </form>
    </main>
  );
}

